library IEEE;
use IEEE.STD_LOGIC_1164.ALL;

-- Uncomment the following library declaration if using
-- arithmetic functions with Signed or Unsigned values
use IEEE.NUMERIC_STD.ALL;

-- Uncomment the following library declaration if instantiating
-- any Xilinx leaf cells in this code.
library UNISIM;
library UNIMACRO;
use UNISIM.VComponents.all;
use UNIMACRO.vcomponents.all;
use work.GraphicsParts.all;

entity read_from_bram is
  Port ( clk : in  STD_LOGIC;
         reset_n : in  STD_LOGIC;
         is_playing: in  STD_LOGIC;
         audio_type: in std_logic_vector (3 downto 0);
         sample_index: in unsigned(16 downto 0);
         data_out: out std_logic_vector(15 downto 0)
        );
end read_from_bram;

architecture Behavioral of read_from_bram is
    signal local_address: unsigned(10 downto 0);
    type bram_array_t is array (0 to 78) of std_logic_vector(15 downto 0);
    signal bram_out: bram_array_t;   
    signal reset: std_logic;
begin
    reset <= not reset_n;
    local_address <= sample_index(10 downto 0);
    --audio type
    -- platform => "00"
    -- spring => "01"
    -- GAME OVER-> 10
    --BROKEN BEM 11
    -- JETPACK 100
    data_out <= bram_out(TO_INTEGER(sample_index(16 downto 11))) when (is_playing = '1' and audio_type = "0000") else 
                bram_out(TO_INTEGER(sample_index(16 downto 11) + 2)) when (is_playing = '1' and audio_type = "0001") else 
                bram_out(TO_INTEGER(sample_index(16 downto 11) + 16)) when (is_playing = '1' and audio_type = "0010") else
                bram_out(TO_INTEGER(sample_index(16 downto 11)) + 49) when (is_playing = '1' and audio_type = "0011") else -- broken
                bram_out(TO_INTEGER(sample_index(16 downto 11)) + 55) when (is_playing = '1' and audio_type = "0100") else

                (others => '0');
                
    
          -- BRAM_SDP_MACRO: Simple Dual Port RAM for Artix-7.  Further details can be found in the
   --  language templates or on the resources page on the course website. 
   platformSoundBRAM_0 : BRAM_SDP_MACRO
   generic map (
      BRAM_SIZE => "36Kb", -- Target BRAM, "18Kb" or "36Kb" 
      DEVICE => "7SERIES", -- Target device: "VIRTEX5", "VIRTEX6", "7SERIES", "SPARTAN6" 
      WRITE_WIDTH => 16,    -- Valid values are 1-72 (37-72 only valid when BRAM_SIZE="36Kb")
      READ_WIDTH => 16,     -- Valid values are 1-72 (37-72 only valid when BRAM_SIZE="36Kb")
      DO_REG => 0, -- Optional output register (0 or 1)
      INIT_FILE => "NONE",
      SIM_COLLISION_CHECK => "NONE", -- Collision check enable "ALL", "WARNING_ONLY", 
                                    -- "GENERATE_X_ONLY" or "NONE"       
      SRVAL => X"00000000000000000000000000000000",
      INIT  => X"00000000000000000000000000000000",
