      port map (
        DO => bram_out(19),   -- Output read data port, width defined by READ_WIDTH parameter
        DI => x"0000",      -- Input write data port, width defined by WRITE_WIDTH parameter
        RDADDR => std_logic_vector(local_address),  -- Input read address, width defined by read port depth
        RDCLK => clk,     -- 1-bit input read clock
        RDEN => '1',      -- 1-bit input read port enable
        REGCE => '1',     -- 1-bit input read output register enable
        RST => reset,     -- 1-bit input reset_n 
        WE => "00",       -- Input write enable, width defined by write port depth
        WRADDR => "000"&x"00",  -- Input write address, width defined by write port depth
        WRCLK => clk,     -- 1-bit input write clock
        WREN => '0'       -- 1-bit input write port enable
      );
      
